def _missing_llm_extra(error: ImportError) -> SystemExit:
    return SystemExit(
        'LLM build/run/benchmark requires `axelera.transformers`. Install `axelera-zoo[llm]` '
        'or run from the all-hf environment.'
    )


def _build_deps():
    try:
        import axelera.transformers
        import torch
        import transformers
        from axelera.transformers import HardwareGeneration
        from axelera.transformers.data_processing import (
            get_multi_dataset_calibration_dataloader,
        )
    except ImportError as error:
        raise _missing_llm_extra(error) from error
    return (
        axelera.transformers,
        torch,
        transformers,
        HardwareGeneration,
        get_multi_dataset_calibration_dataloader,
    )


def _run_deps():
    try:
        import axelera.transformers
        import transformers
    except ImportError as error:
        raise _missing_llm_extra(error) from error
    return axelera.transformers, transformers


def build(
    output_dir: Path,
    seq_len: int,
    cal_device: str | None,
    load_to_device: bool,
    quantized_model: Path | None = None,
) -> None:
    (
        ax_transformers,
        torch,
        transformers,
        HardwareGeneration,
        get_multi_dataset_calibration_dataloader,
    ) = _build_deps()
    device = torch.device(cal_device or ('cuda' if torch.cuda.is_available() else 'cpu'))

    tokenizer = transformers.AutoTokenizer.from_pretrained(MODEL_NAME)
    if quantized_model is not None:
        print(f'Loading pre-quantized model from: {quantized_model} (skipping PTQ)')
        model = ax_transformers.AxLMTransformerForCausalLM.load(quantized_model)
        model.to(device)
    else:
        print(f'Loading model: {MODEL_NAME}')
        model = ax_transformers.AxLMTransformerForCausalLM.from_pretrained(MODEL_NAME)
        model.to(device)

        print('Running post-training quantization (PTQ)...')
        print(f'  - Calibration samples: {NUM_CAL}')
        print(f'  - SmoothQuant alpha:   {SMOOTH_QUANT_ALPHA}')
        print(f'  - SmoothQuant QK alpha:{SMOOTH_QK_ALPHA}')
        cal_loader = get_multi_dataset_calibration_dataloader(
            tokenizer=tokenizer,
            num_samples=NUM_CAL,
            batch_size=CALIBRATION_BATCH_SIZE,
            block_size=seq_len,
            wikitext_ratio=WIKITEXT_RATIO,
            mmlu_ratio=MMLU_RATIO,
            hellaswag_ratio=HELLASWAG_RATIO,
            include_chat_samples=INCLUDE_CHAT_SAMPLES,
        )
        model.optimize(
            generation=HardwareGeneration.METIS,
            calibration_dataloader=cal_loader,
            smooth_quant_alpha=SMOOTH_QUANT_ALPHA,
            smooth_qk_alpha=SMOOTH_QK_ALPHA,
            device=device,
            progress_bar=True,
        )
        print('Post-training quantization complete.')
        # Saved so can be reused later for QAT, inspection, or rebuilding from the same quantized model
        model.save(output_dir / 'quantized_model')

    print(f'Compiling model to: {output_dir}')
    model.compile(
        output_dir=str(output_dir),
        generation=HardwareGeneration.METIS,
        max_seq_len=seq_len,
        load_to_device=load_to_device,
    )
    tokenizer.save_pretrained(output_dir)
    print(f'Compilation complete. Artifacts written to: {output_dir}')


def run(
    output_dir: Path,
    prompt: str,
    max_new_tokens: int,
    *,
    chat: bool,
    sample: bool,
    device_id: int,
) -> None:
    if max_new_tokens < 1:
        raise SystemExit(f'--max-new-tokens must be >= 1 (got {max_new_tokens})')
    if device_id < 0:
        raise SystemExit(f'--device-id must be >= 0 (got {device_id})')
    ax_transformers, transformers = _run_deps()
    print(f'Loading compiled model from: {output_dir}')
    model = ax_transformers.AxLMTransformerForCausalLM.load_compiled(
        str(output_dir), device_id=device_id
    )
    tokenizer = transformers.AutoTokenizer.from_pretrained(output_dir)
    if tokenizer.pad_token is None:
        tokenizer.pad_token = tokenizer.eos_token

    device = next(model.parameters()).device
    if chat:
        input_ids = tokenizer.apply_chat_template(
            [{'role': 'user', 'content': prompt}],
            add_generation_prompt=True,
            return_tensors='pt',
            tokenize=True,
        ).to(device)
        output_ids = model.generate(
            input_ids,
            max_new_tokens=max_new_tokens,
            do_sample=sample,
            use_cache=True,
        )
    else:
        inputs = tokenizer(text=prompt, return_tensors='pt').to(device)
        output_ids = model.generate(
            **inputs,
            max_new_tokens=max_new_tokens,
            do_sample=sample,
            use_cache=True,
        )
    print(tokenizer.decode(output_ids[0], skip_special_tokens=True))


try:
    from transformers import BaseStreamer as _BaseStreamer
except ImportError:

    class _BaseStreamer:
        """Fallback so this recipe imports before `axelera.transformers` is installed."""


class GenerationStats(NamedTuple):
    """Token-generation timings for one benchmark sample.

    A NamedTuple rather than a dataclass: a dataclass resolves its annotations
    through `sys.modules[__module__]`, which is absent when a tool executes this
    recipe's source instead of importing it by name.
    """

    load_time_s: float
    tokenize_time_ms: float
    prompt_tokens: int
    prefill_time_s: float
    ttft_s: float
    decode_time_s: float
    inter_token_latency_ms: tuple[float, ...]
    output_tokens_per_s: float
    generated_tokens: int
    total_tokens: int


class BenchmarkResult(NamedTuple):
    """Cold-load time and the measured generation samples."""

    load_time_s: float
    samples: tuple[GenerationStats, ...]
    device_ids: tuple[int, ...] = (0,)
    aggregate_end_to_end_output_tokens_per_s: float = 0.0


class FirstTokenStreamer(_BaseStreamer):
    """Record first-token and inter-token generation timings."""

    def __init__(self, *, skip_prompt: bool = True) -> None:
        self._skip_next = skip_prompt
        self.first_token_time_s: float | None = None
        self.token_times_s: list[float] = []

    def put(self, _value) -> None:
        if self._skip_next:
            self._skip_next = False
            return
        now = time.perf_counter()
        if self.first_token_time_s is None:
            self.first_token_time_s = now
        self.token_times_s.append(now)

    def end(self) -> None:
        return


# Kept literal rather than imported: a recipe reaches no zoo module, and
# `build.config.LLM_WORKLOADS` is the same tuple the CLI validates against
# (`test_recipe_workload_choices_match_the_library` keeps the two in step).
WORKLOADS = ('generate', 'prefill', 'decode')

# Seed prompt for the decode workload. Two tokens is the smallest prompt that is
# unambiguously a prefill pass -- a single-token forward over an empty cache is
# indistinguishable by shape from a decode step -- and keeping it minimal leaves
# the whole sequence-length budget for timed decode steps.
DECODE_SEED_TOKENS = 2

# Decode steps dropped from the step aggregates. A decode trajectory is measured cold,
# so its first steps carry warm-up cost; the compiler LLM regression job drops
# exactly three (`step_times[num_warmup:]`, `--num-warmup` default 3) and errors when
# that leaves none. Keeping them would report a mean that cannot be compared against
# that job's, which is material at short sequence lengths -- 3 of 122 steps at 128.
DECODE_WARMUP_STEPS = 3

# Filler for a fixed-length prompt: repeated, then sliced to the exact token
# count. Prefill cost depends on the token count rather than the text, so this
# needs no dataset, which keeps the benchmark offline and deterministic.
_PROMPT_FILLER = 'An AI accelerator executes neural network inference on dedicated hardware. '


def artifact_metadata(output_dir) -> dict:
    """Parse a built artifact's `metadata.json`, which `model.compile` writes.

    Everything describing WHAT was compiled is read from here rather than from the
    config or a build knob: this recipe is rendered in-process by `axzoo benchmark`
    without the build env set, so its constants describe the config, not the
    directory being measured. The compiler LLM regression job reads the
    same file for the same reason.
    """
    meta = Path(output_dir) / 'metadata.json'
    if not meta.is_file():
        raise SystemExit(
            f'{meta} is missing, so the compiled sequence length is unknown; '
            f'build this directory first.'
        )
    try:
        return json.loads(meta.read_text())
    except json.JSONDecodeError as error:
        raise SystemExit(f'{meta} is not valid JSON: {error}') from error


def compiled_seq_len(output_dir) -> int:
    """Return the largest compiled bucket recorded in the artifact."""
    seq_lens = artifact_metadata(output_dir).get('compiled_seq_lens')
    if not seq_lens:
        raise SystemExit(f'{Path(output_dir) / "metadata.json"} declares no compiled_seq_lens.')
    return max(int(seq_len) for seq_len in seq_lens)


def compiled_model_name(output_dir, default: str) -> str:
    """Return the model id recorded in the artifact, else `default`.

    `model` leads the CSV and is one of the three columns the report step indexes
    on, so a row measuring one artifact must not be keyed on whichever config the
    CLI happened to resolve -- `--output-dir` can point anywhere. `model.compile`
    records the id from `config._name_or_path`; the regression job reads the same
    field, so both label a given artifact identically.
    """
    return artifact_metadata(output_dir).get('name_or_path') or default


def resolve_workload(workload: str, max_new_tokens: int, seq_len, compiled_seq_len: int):
    """Return `(prompt_tokens, token_count)` for a workload.

    `token_count` is the tokens to generate for `generate` / `prefill`, and the
    decode-step count for `decode`, which `measure_decode` spends on timed forwards.

    Prefill and decode share one sequence-length budget, so a run can only sit at
    one end of it: `prefill` spends the budget on the prompt and generates a single
    token, `decode` seeds minimally and spends the rest on timed decode steps.
    `generate` leaves the caller's prompt and token count alone.

    `prompt_tokens` of None means "use the caller's prompt text".
    """
    if workload not in WORKLOADS:
        raise ValueError(f'workload must be one of {list(WORKLOADS)} (got {workload!r})')
    if workload == 'generate':
        return None, max_new_tokens
    if seq_len is None:
        raise ValueError(f'--seq-len is required for --workload {workload}')
    if seq_len > compiled_seq_len:
        raise ValueError(
            f'--seq-len {seq_len} exceeds the compiled sequence length {compiled_seq_len}; '
            f'rebuild with a larger --seq-len to measure it.'
        )
    if workload == 'prefill':
        if seq_len < DECODE_SEED_TOKENS:
            raise ValueError(f'--seq-len must be >= {DECODE_SEED_TOKENS} (got {seq_len})')
        return seq_len, 1
    steps = seq_len - DECODE_SEED_TOKENS
    if steps < 1:
        raise ValueError(
            f'--seq-len {seq_len} leaves no decode steps after the '
            f'{DECODE_SEED_TOKENS}-token seed prefill.'
        )
    # `steps` tokens yield `steps - 1` timed gaps, of which the first
    # DECODE_WARMUP_STEPS are dropped. Refused here rather than after the run, so a
    # sequence length too short to report a step mean fails before the trajectory.
    if steps - 1 <= DECODE_WARMUP_STEPS:
        raise ValueError(
            f'--seq-len {seq_len} leaves {max(steps - 1, 0)} decode step(s), all consumed '
            f'by the {DECODE_WARMUP_STEPS}-step warm-up drop; raise --seq-len.'
        )
    return DECODE_SEED_TOKENS, steps


# The regression job wraps each of these timings in a `torch.cuda.synchronize()`
# barrier, which this deliberately omits: it guards against a forward returning before
# an async device finishes, and the compiled path has no async device to wait for. The
# loader and the runtime wrapper reference CUDA nowhere, and `benchmark` only ever loads
# a compiled model -- CUDA reaches this recipe solely through calibration, on the build
# path. Restore the barrier if the embed / lm_head path is ever placed on a GPU.


def time_prefill(model, input_ids):
    """One prefill forward: `(elapsed_s, past_key_values, last_position_logits)`."""
    start = time.perf_counter()
    out = model(input_ids=input_ids, use_cache=True)
    return time.perf_counter() - start, out.past_key_values, out.logits[:, -1, :]


def time_decode_step(model, next_token, past_key_values):
    """One decode forward: `(elapsed_s, next_token, past_key_values)`.

    The clock stops BEFORE the argmax that picks the next token, so the sample is
    the forward and nothing else.
    """
    start = time.perf_counter()
    out = model(input_ids=next_token, past_key_values=past_key_values, use_cache=True)
    elapsed = time.perf_counter() - start
    return elapsed, out.logits[:, -1, :].argmax(dim=-1, keepdim=True), out.past_key_values


def _check_cache_length(past_key_values, prompt_tokens: int, forwards: int) -> None:
    """The cache holds the seed plus one entry per decode forward, and nothing else.

    The Nth generated token's own KV is never in the cache -- an (N+1)th forward
    would append it -- which is why the expected length is short of the token count.
    A mismatch means the step samples cover a different cache range than the row
    claims, so it is reported rather than averaged over.
    """
    length = getattr(past_key_values, 'get_seq_length', lambda: None)()
    expected = prompt_tokens + forwards
    if length is not None and int(length) != expected:
        raise SystemExit(
            f'KV cache holds {length} entries, expected {expected} (seed {prompt_tokens} '
            f'+ {forwards} decode forwards); the step aggregates would cover the wrong range.'
        )


def _decode_trajectory(model, tokenizer, prompt_ids, steps: int, load_time_s: float):
    """Seed prefill, first token, then `steps - 1` timed decode forwards.

    Time to first token is the seed forward plus the argmax and detokenization of
    the first token -- what a streaming caller waits for before seeing a character,
    and the same bracket the regression job reports. The first DECODE_WARMUP_STEPS
    forwards are dropped from the step samples: a trajectory is measured cold, so
    they carry warm-up cost.
    """
    prefill_s, past, last_logits = time_prefill(model, prompt_ids)
    post_start = time.perf_counter()
    first_token = last_logits.argmax(dim=-1, keepdim=True)
    tokenizer.decode(first_token[0].tolist(), skip_special_tokens=True)
    ttft_s = prefill_s + (time.perf_counter() - post_start)

    next_token = first_token
    step_times: list[float] = []
    for _ in range(steps - 1):
        elapsed, next_token, past = time_decode_step(model, next_token, past)
        step_times.append(elapsed)

    prompt_tokens = int(prompt_ids.shape[-1])
    _check_cache_length(past, prompt_tokens, len(step_times))
    timed = step_times[DECODE_WARMUP_STEPS:]
    if not timed:
        raise SystemExit(
            f'every decode step was consumed by the {DECODE_WARMUP_STEPS}-step warm-up '
            f'drop; raise --seq-len.'
        )
    decode_time_s = sum(step_times)
    return GenerationStats(
        load_time_s=load_time_s,
        tokenize_time_ms=0.0,
        prompt_tokens=prompt_tokens,
        prefill_time_s=prefill_s,
        ttft_s=ttft_s,
        decode_time_s=decode_time_s,
        inter_token_latency_ms=tuple(elapsed * 1000.0 for elapsed in timed),
        output_tokens_per_s=steps / decode_time_s if decode_time_s > 0 else 0.0,
        generated_tokens=steps,
        total_tokens=prompt_tokens + steps,
    )


def _no_grad():
    """`torch.no_grad()` where torch is installed, else a no-op.

    Driving the model directly means driving it OUTSIDE `generate`, which carries
    `@torch.no_grad()` as a decorator. Without it the forwards build a graph and the
    compiled runtime fails on the very first one -- it hands its inputs to `.numpy()`,
    which refuses a tensor that requires grad -- and the samples would carry
    graph-construction cost that `generate` never pays.

    Torch is imported here rather than at module scope, and its absence is not an
    error: this recipe stays importable without the LLM stack (`test_recipe_standalone`
    pins that), and the workload tests drive a fake model so they run in the zoo-only
    env. A caller with no torch has no autograd to disable, so there is nothing to
    guard.
    """
    try:
        import torch
    except ImportError:
        return contextlib.nullcontext()
    return torch.no_grad()


def measure_decode(
    model,
    tokenizer,
    *,
    steps: int,
    device,
    warmup: int = 0,
    iterations: int = 1,
    load_time_s: float = 0.0,
    device_id: int = 0,
) -> BenchmarkResult:
    """Measure decode by driving the model directly, not through `generate`.

    `generate` cannot produce this measurement. Its only per-step hook is the
    streamer callback, which fires BETWEEN forwards, so a sample taken from it also
    spans the float32 logits copy, the processor list, the argmax and two host
    copies -- overhead repeated every step, which biases the step mean high against
    the job's forward-only sample. It also brackets time to first token differently
    and cannot report the job's, and which of two call paths it uses per step is a
    transformers implementation detail that has no reason to hold across releases.

    `generate` remains what the `generate` workload measures, where that overhead
    is part of the answer rather than noise in it.
    """
    _check_measure_args(steps, warmup, iterations)
    ids = prompt_input_ids(tokenizer, DECODE_SEED_TOKENS)
    prompt_ids = ids if device is None else ids.to(device)
    with _no_grad():
        for _ in range(warmup):
            _decode_trajectory(model, tokenizer, prompt_ids, steps, 0.0)
        measured_start = time.perf_counter()
        samples = tuple(
            _decode_trajectory(model, tokenizer, prompt_ids, steps, load_time_s)
            for _ in range(iterations)
        )
    return _result(samples, (device_id,), load_time_s, time.perf_counter() - measured_start)


def prompt_input_ids(tokenizer, prompt_tokens: int):
    """Return a `(1, prompt_tokens)` tensor holding exactly `prompt_tokens` tokens."""
    repeats = 1
    while True:
        ids = tokenizer(_PROMPT_FILLER * repeats, return_tensors='pt')['input_ids']
        if ids.shape[-1] >= prompt_tokens:
            return ids[:, :prompt_tokens]
        repeats *= 2


def timed_generate(
    model,
    tokenizer,
    *,
    prompt: str | None = None,
    input_ids=None,
    max_new_tokens: int,
    device,
    load_time_s: float = 0.0,
) -> GenerationStats:
    """Run deterministic generation and return its token timings.

    Prefill is timed by wrapping `model.forward`: the first call is the prompt
    pass, every later one decodes a single token. Time to first token and the
    inter-token gaps come from the streamer, which sees each token as it lands.

    Pass exactly one of `prompt` (tokenized here) or `input_ids` (already a
    `(1, N)` tensor). `input_ids` is how a caller pins the prompt to an exact
    token count: decoding a fixed-length block back to text and re-encoding it
    does not preserve the length.
    """
    if (prompt is None) == (input_ids is None):
        raise ValueError('pass exactly one of prompt= or input_ids=')

    tokenize_start = time.perf_counter()
    if prompt is not None:
        inputs = tokenizer(text=prompt, return_tensors='pt')
        if device is not None:
            inputs = inputs.to(device)
    else:
        ids = input_ids if device is None else input_ids.to(device)
        inputs = {'input_ids': ids, 'attention_mask': ids.new_ones(ids.shape)}
    prompt_tokens = int(inputs['input_ids'].shape[-1])
    tokenize_time_ms = (time.perf_counter() - tokenize_start) * 1000.0

    prefill_time_s = 0.0
    prefill_seen = False
    original_forward = model.forward

    def timed_forward(*args, **kwargs):
        nonlocal prefill_seen, prefill_time_s
        start = time.perf_counter()
        result = original_forward(*args, **kwargs)
        if not prefill_seen:
            prefill_time_s = time.perf_counter() - start
            prefill_seen = True
        return result

    streamer = FirstTokenStreamer(skip_prompt=True)
    model.forward = timed_forward
    generation_start = time.perf_counter()
    try:
        output_ids = model.generate(
            **inputs,
            max_new_tokens=max_new_tokens,
            do_sample=False,
            use_cache=True,
            streamer=streamer,
        )
    finally:
        model.forward = original_forward
    generation_end = time.perf_counter()

    generated_tokens = max(0, int(output_ids.shape[-1]) - prompt_tokens)
    first_token_time = streamer.first_token_time_s or generation_end
    generation_time_s = max(generation_end - generation_start, 0.0)
    token_times = streamer.token_times_s
    return GenerationStats(
        load_time_s=load_time_s,
        tokenize_time_ms=tokenize_time_ms,
        prompt_tokens=prompt_tokens,
        prefill_time_s=prefill_time_s,
        ttft_s=max(first_token_time - generation_start, 0.0),
        decode_time_s=max(generation_end - first_token_time, 0.0),
        inter_token_latency_ms=tuple(
            (right - left) * 1000.0
            for left, right in zip(token_times, token_times[1:], strict=False)
        ),
        output_tokens_per_s=generated_tokens / generation_time_s if generation_time_s > 0 else 0.0,
        generated_tokens=generated_tokens,
        total_tokens=prompt_tokens + generated_tokens,
    )


def measure(
    model,
    tokenizer,
    *,
    prompt: str | None = None,
    input_ids=None,
    max_new_tokens: int,
    device,
    warmup: int = 1,
    iterations: int = 10,
    load_time_s: float = 0.0,
    device_id: int = 0,
) -> BenchmarkResult:
    """Measure repeated deterministic generation on one device, after warmup.

    `prompt` / `input_ids` are forwarded to `timed_generate` unchanged; see it
    for their contract.
    """
    _check_measure_args(max_new_tokens, warmup, iterations)
    for _ in range(warmup):
        timed_generate(
            model,
            tokenizer,
            prompt=prompt,
            input_ids=input_ids,
            max_new_tokens=max_new_tokens,
            device=device,
        )
    measured_start = time.perf_counter()
    samples = tuple(
        timed_generate(
            model,
            tokenizer,
            prompt=prompt,
            input_ids=input_ids,
            max_new_tokens=max_new_tokens,
            device=device,
            load_time_s=load_time_s,
        )
        for _ in range(iterations)
    )
    return _result(samples, (device_id,), load_time_s, time.perf_counter() - measured_start)


def measure_many(
    runners,
    *,
    prompt: str | None = None,
    input_ids=None,
    max_new_tokens: int,
    warmup: int = 1,
    iterations: int = 10,
    load_time_s: float = 0.0,
) -> BenchmarkResult:
    """Measure concurrent generation across one model instance per AIPU."""
    if not runners:
        raise ValueError('at least one device is required')
    device_ids = tuple(device_id for device_id, _model, _tokenizer, _device in runners)
    if any(device_id < 0 for device_id in device_ids):
        raise ValueError('device IDs must be >= 0')
    if len(set(device_ids)) != len(device_ids):
        raise ValueError('device IDs must not contain duplicates')
    _check_measure_args(max_new_tokens, warmup, iterations)

    def generate_once(runner) -> GenerationStats:
        _device_id, model, tokenizer, device = runner
        return timed_generate(
            model,
            tokenizer,
            prompt=prompt,
            input_ids=input_ids,
            max_new_tokens=max_new_tokens,
            device=device,
            load_time_s=load_time_s,
        )

    def generate_iterations(runner) -> tuple[GenerationStats, ...]:
        return tuple(generate_once(runner) for _ in range(iterations))

    with ThreadPoolExecutor(max_workers=len(runners)) as pool:
        for _ in range(warmup):
            tuple(pool.map(generate_once, runners))
        measured_start = time.perf_counter()
        samples_by_device = tuple(pool.map(generate_iterations, runners))
        measured_time_s = time.perf_counter() - measured_start

    samples = tuple(sample for device_samples in samples_by_device for sample in device_samples)
    return _result(samples, device_ids, load_time_s, measured_time_s)


def _check_measure_args(max_new_tokens: int, warmup: int, iterations: int) -> None:
    if max_new_tokens < 1:
        raise ValueError(f'max_new_tokens must be >= 1 (got {max_new_tokens})')
    if warmup < 0:
        raise ValueError(f'warmup must be >= 0 (got {warmup})')
    if iterations < 1:
        raise ValueError(f'iterations must be >= 1 (got {iterations})')


def _result(
    samples: tuple[GenerationStats, ...],
    device_ids: tuple[int, ...],
    load_time_s: float,
    measured_time_s: float,
) -> BenchmarkResult:
    """Assemble a result, dividing total generated tokens by the measured wall."""
    generated_tokens = sum(sample.generated_tokens for sample in samples)
    return BenchmarkResult(
        load_time_s=load_time_s,
        samples=samples,
        device_ids=device_ids,
        aggregate_end_to_end_output_tokens_per_s=(
            generated_tokens / measured_time_s if measured_time_s > 0 else 0.0
        ),
    )


def _percentile(sorted_ms: list[float], q: float) -> float:
    """Linear-interpolated q-quantile (q in [0,1]) of an ascending-sorted list."""
    if not sorted_ms:
        return 0.0
    k = (len(sorted_ms) - 1) * q
    lo = int(k)
    hi = min(lo + 1, len(sorted_ms) - 1)
    return sorted_ms[lo] + (sorted_ms[hi] - sorted_ms[lo]) * (k - lo)


def _summary(result: BenchmarkResult) -> dict[str, float]:
    """Flatten a result into the one metric-per-key shape the report and CSV share."""
    fields = (
        'load_time_s',
        'tokenize_time_ms',
        'prompt_tokens',
        'prefill_time_s',
        'ttft_s',
        'decode_time_s',
        'itl_mean',
        'itl_p50',
        'itl_p95',
        'itl_p99',
        'itl_max',
        'output_tokens_per_s',
        'aggregate_end_to_end_output_tokens_per_s',
        'generated_tokens',
        'total_tokens',
    )
    samples = result.samples
    if not samples:
        return dict.fromkeys(fields, 0.0) | {'load_time_s': result.load_time_s}
    inter_token_ms = sorted(v for sample in samples for v in sample.inter_token_latency_ms)
    return {
        'load_time_s': result.load_time_s,
        'tokenize_time_ms': statistics.fmean(s.tokenize_time_ms for s in samples),
        'prompt_tokens': float(samples[-1].prompt_tokens),
        'prefill_time_s': statistics.fmean(s.prefill_time_s for s in samples),
        'ttft_s': statistics.fmean(s.ttft_s for s in samples),
        'decode_time_s': statistics.fmean(s.decode_time_s for s in samples),
        'itl_mean': statistics.fmean(inter_token_ms) if inter_token_ms else 0.0,
        'itl_p50': _percentile(inter_token_ms, 0.50),
        'itl_p95': _percentile(inter_token_ms, 0.95),
        'itl_p99': _percentile(inter_token_ms, 0.99),
        'itl_max': inter_token_ms[-1] if inter_token_ms else 0.0,
        'output_tokens_per_s': statistics.fmean(s.output_tokens_per_s for s in samples),
        'aggregate_end_to_end_output_tokens_per_s': (
            result.aggregate_end_to_end_output_tokens_per_s
        ),
        'generated_tokens': float(samples[-1].generated_tokens),
        'total_tokens': float(samples[-1].total_tokens),
    }


def as_dict(result: BenchmarkResult, *, config: str, model) -> dict:
    """The JSON-ready result shape."""
    return {
        'config': config,
        'model': str(model),
        'device_ids': ','.join(str(device_id) for device_id in result.device_ids),
        **_summary(result),
    }


def format_benchmark(
    result: BenchmarkResult, *, config: str, model, warmup: int, iterations: int
) -> str:
    """Render the token metrics as the human report."""
    s = _summary(result)
    device_ids = ','.join(str(device_id) for device_id in result.device_ids)
    return '\n'.join(
        (
            f'[benchmark] {config}   model={model}   devices={device_ids}   '
            f'warmup={warmup} iterations={iterations}',
            'LLM token metrics:',
            f'  load_time_s {s["load_time_s"]:.3f}',
            f'  tokenize_time_ms {s["tokenize_time_ms"]:.2f}  '
            f'prompt_tokens {s["prompt_tokens"]:.0f}',
            f'  prefill_time_s {s["prefill_time_s"]:.3f}  '
            f'ttft_s {s["ttft_s"]:.3f}  decode_time_s {s["decode_time_s"]:.3f}',
            f'  inter_token_latency_ms mean {s["itl_mean"]:.2f}  '
            f'p50 {s["itl_p50"]:.2f}  p95 {s["itl_p95"]:.2f}  '
            f'p99 {s["itl_p99"]:.2f}  max {s["itl_max"]:.2f}',
            f'  per_device_output_tokens_per_s {s["output_tokens_per_s"]:.2f}  '
            f'aggregate_end_to_end_output_tokens_per_s '
            f'{s["aggregate_end_to_end_output_tokens_per_s"]:.2f}  '
            f'generated_tokens_per_request {s["generated_tokens"]:.0f}  '
            f'total_tokens_per_request {s["total_tokens"]:.0f}',
        )
    )


# The first ten columns are the perf schema the CI report step consumes; it reads
# the CSV with `--index_col model seq_len mode`, so a row missing any of those
# three cannot be converted at all. The remaining columns are extra detail: the
# converter nests every non-index column under the (model, seq_len, mode) key
# without needing to know what they are.
#
# `compile_time` is declared here and left empty by every row this writer produces:
# a benchmark run does not know what the build cost, and `llm_perf_report` fills it
# in per cell afterwards. Declaring it keeps the row width CONSTANT. It used to be
# appended by that rewrite instead, which widened the header while this writer kept
# emitting the narrower row -- so every row appended after the first cell was ragged,
# and the next rewrite only healed them when a build had actually run, never on a
# cache hit. A short row costs `compile_time` its value silently in the report.
CSV_FIELDS = (
    'model',
    'source',
    'mode',
    'batch_size',
    'seq_len',
    'prefill_length',
    'tokens_per_second',
    'ttft_ms',
    'decode_step_mean_ms',
    'prefill_time_ms',
    'load_time_s',
    'itl_p50_ms',
    'itl_p95_ms',
    'itl_p99_ms',
    'itl_max_ms',
    'prompt_tokens',
    'generated_tokens',
    'iterations',
    'device_ids',
    'compile_time',
)


def _existing_header(path: Path) -> list[str] | None:
    """The CSV's header row, or None when the file is absent or empty."""
    if not path.exists() or path.stat().st_size == 0:
        return None
    with path.open(newline='', encoding='utf-8') as handle:
        return next(csv.reader(handle), None)


def write_csv(
    path: Path,
    result: BenchmarkResult,
    *,
    model: str,
    source,
    workload: str,
    seq_len: int,
) -> None:
    """Append one summary row for this run; write the header only when new.

    `workload` selects which measurement is the row's headline, and which columns
    stay empty, so a row means the same thing as the corresponding row of the
    compiler LLM regression job:

    - `prefill` reports prompt tokens over the prefill pass, and leaves every
      gap-derived column empty, since one generated token yields no gaps. That
      includes `ttft_ms`: with the prefill pass dominating time-to-first-token, it
      would only restate `prefill_time_ms`.
    - `decode` / `generate` report the steady-state decode rate -- the reciprocal
      of the mean inter-token gap, so the seed prefill is excluded -- plus TTFT and
      that gap.
    """
    path.parent.mkdir(parents=True, exist_ok=True)
    summary = _summary(result)
    prefill_ms = summary['prefill_time_s'] * 1000.0
    itl_mean_ms = summary['itl_mean']
    if workload == 'prefill':
        prompt_tokens = summary['prompt_tokens']
        tokens_per_second = (
            prompt_tokens / summary['prefill_time_s'] if summary['prefill_time_s'] > 0 else 0.0
        )
        # A prefill run generates one token, so it has no inter-token gaps at all.
        # Every gap-derived column is left empty rather than zero: the report step
        # nests each one under this row's key, and a zero would plot as a real
        # measurement and drag any aggregate across workloads down with it.
        # `prefill_length` is NOT one of those: this is the only workload that
        # measures a prompt length, so it is the only one that can report it.
        row = {
            'prefill_length': prompt_tokens,
            'tokens_per_second': tokens_per_second,
            'ttft_ms': '',
            'decode_step_mean_ms': '',
            'itl_p50_ms': '',
            'itl_p95_ms': '',
            'itl_p99_ms': '',
            'itl_max_ms': '',
        }
    else:
        row = {
            # Blank, not `prompt_tokens`: under this workload that is the 2-token
            # decode seed, so filling it would publish a constant 2 as a prefill
            # length on every decode row.
            'prefill_length': '',
            'tokens_per_second': 1000.0 / itl_mean_ms if itl_mean_ms > 0 else 0.0,
            'ttft_ms': summary['ttft_s'] * 1000.0,
            'decode_step_mean_ms': itl_mean_ms,
            'itl_p50_ms': summary['itl_p50'],
            'itl_p95_ms': summary['itl_p95'],
            'itl_p99_ms': summary['itl_p99'],
            'itl_max_ms': summary['itl_max'],
        }
    row.update(
        model=model,
        source=str(source),
        mode=workload,
        batch_size=1,
        seq_len=seq_len,
        prefill_time_ms=prefill_ms,
        load_time_s=summary['load_time_s'],
        prompt_tokens=summary['prompt_tokens'],
        generated_tokens=summary['generated_tokens'],
        iterations=len(result.samples),
        device_ids=','.join(str(device_id) for device_id in result.device_ids),
    )
    # Compared rather than inferred from emptiness: every cell of a tier appends from
    # a fresh subprocess, so a file written under a different schema (an older recipe,
    # or the regression job's own narrower CSV) would otherwise be appended to with a
    # row of the wrong width, and the report would read the columns out of step.
    header = _existing_header(path)
    if header is not None and header != list(CSV_FIELDS):
        raise SystemExit(
            f'{path} has {len(header)} columns, this recipe writes {len(CSV_FIELDS)}; '
            f'appending would produce ragged rows. Point --output-csv at a new file.'
        )
    with path.open('a', newline='', encoding='utf-8') as handle:
        writer = csv.DictWriter(handle, fieldnames=CSV_FIELDS)
        if header is None:
            writer.writeheader()
        writer.writerow(row)


def benchmark(
    output_dir: Path,
    prompt: str | None,
    max_new_tokens: int,
    *,
    warmup: int,
    iterations: int,
    output_csv: Path | None,
    json_output: bool,
    device_ids: tuple[int, ...] = (0,),
    config_name: str = MODEL_ID,
    workload: str = 'generate',
    seq_len: int | None = None,
) -> None:
    if workload not in WORKLOADS:
        raise SystemExit(f'--workload must be one of {list(WORKLOADS)} (got {workload!r})')
    # The prefill and decode workloads build their own prompt at an exact token
    # count, so a supplied one has nowhere to go; taking it and ignoring it would
    # report a synthetic prompt's timings as if they were this prompt's.
    if workload != 'generate' and prompt is not None:
        raise SystemExit(f'--prompt applies only to --workload generate, not {workload}')
    # The mirror of that: `generate` measures the caller's prompt, so there is no
    # sequence-length budget to spend and --seq-len shapes nothing. Accepting it
    # anyway would still LABEL the row with it -- the CSV is keyed on
    # (model, seq_len, mode) -- so a default-prompt run would be filed as a
    # measurement at that length. Both are pure argument checks, so they stay ahead
    # of the artifact and no caller can produce a mislabelled row.
    if workload == 'generate' and seq_len is not None:
        raise SystemExit(
            f'--seq-len applies only to --workload prefill/decode, not {workload}; it would '
            f'label the row {seq_len} without changing what was measured'
        )
    if prompt is None:
        prompt = DEFAULT_PROMPT
    # Checked on the caller's value, ahead of the artifact: resolution overrides it for
    # prefill (1) and decode (the step count, already >= 1), so `generate` is the only
    # workload where the two differ and this is the only place it can be wrong.
    if max_new_tokens < 1:
        raise SystemExit(f'--max-new-tokens must be >= 1 (got {max_new_tokens})')
    if warmup < 0:
        raise SystemExit(f'--warmup must be >= 0 (got {warmup})')
    if iterations < 1:
        raise SystemExit(f'--iterations must be >= 1 (got {iterations})')
    if not device_ids:
        raise SystemExit('--device-ids requires at least one device')
    if any(device_id < 0 for device_id in device_ids):
        raise SystemExit('--device-ids values must be >= 0')
    if len(set(device_ids)) != len(device_ids):
        raise SystemExit('--device-ids must not contain duplicates')
    # The regression job's decode leg drives one device, and `measure_decode` threads a
    # single KV cache through one trajectory. Refused rather than silently measuring
    # only the first device.
    if workload == 'decode' and len(device_ids) != 1:
        raise SystemExit(f'--workload decode measures one device (got {len(device_ids)})')
    if not output_dir.is_dir():
        raise SystemExit(f'model not built: {output_dir}; build the recipe first')
    # The bucket on disk, not COMPILE_SEQ_LEN: `axzoo benchmark` renders this recipe
    # in-process without AXZOO_COMPILE_SEQ_LEN set, so the constant is whatever the
    # config declared and says nothing about the directory being measured -- which
    # `axzoo build --seq-len` may well have built at another length.
    built_seq_len = compiled_seq_len(output_dir)
    try:
        prompt_tokens, token_count = resolve_workload(
            workload, max_new_tokens, seq_len, built_seq_len
        )
    except ValueError as error:
        raise SystemExit(str(error)) from error
    ax_transformers, transformers = _run_deps()
    load_start = time.perf_counter()
    runners = []
    for device_id in device_ids:
        model = ax_transformers.AxLMTransformerForCausalLM.load_compiled(
            str(output_dir), device_id=device_id
        )
        tokenizer = transformers.AutoTokenizer.from_pretrained(output_dir)
        if tokenizer.pad_token is None:
            tokenizer.pad_token = tokenizer.eos_token
        runners.append((device_id, model, tokenizer, next(model.parameters()).device))
    load_time_s = time.perf_counter() - load_start
    if workload == 'decode':
        # Driven directly rather than through `generate`: see `measure_decode` for why
        # that is the only way to sample the forward alone and to bracket time to first
        # token the way the regression job does.
        device_id, model, tokenizer, device = runners[0]
        result = measure_decode(
            model,
            tokenizer,
            steps=token_count,
            device=device,
            warmup=warmup,
            iterations=iterations,
            load_time_s=load_time_s,
            device_id=device_id,
        )
    else:
        input_ids = None
        if prompt_tokens is not None:
            input_ids = prompt_input_ids(runners[0][2], prompt_tokens)
            prompt = None
        if len(runners) == 1:
            device_id, model, tokenizer, device = runners[0]
            result = measure(
                model,
                tokenizer,
                prompt=prompt,
                input_ids=input_ids,
                max_new_tokens=token_count,
                device=device,
                warmup=warmup,
                iterations=iterations,
                load_time_s=load_time_s,
                device_id=device_id,
            )
        else:
            result = measure_many(
                tuple(runners),
                prompt=prompt,
                input_ids=input_ids,
                max_new_tokens=token_count,
                warmup=warmup,
                iterations=iterations,
                load_time_s=load_time_s,
            )
    if output_csv is not None:
        write_csv(
            output_csv,
            result,
            model=compiled_model_name(output_dir, MODEL_NAME),
            source=output_dir,
            workload=workload,
            seq_len=seq_len if seq_len is not None else built_seq_len,
        )
    if json_output:
        print(json.dumps(as_dict(result, config=config_name, model=output_dir)))
        return
    print(
        format_benchmark(
            result,
            config=config_name,
            model=output_dir,
            warmup=warmup,
            iterations=iterations,
        )
    )


def build_default() -> None:
    """The programmatic build entry `axzoo build` uses (see build/_script_runner.py).

    The compile params come from the module constants, which already absorb the AXZOO_*
    overrides the runner sets, so the runner needs to pass nothing.
    """
    build(
        OUTPUT_DIR,
        COMPILE_SEQ_LEN,
        None,
        load_to_device=True,
        quantized_model=QUANTIZED_MODEL,
    )


def evaluate(
    output_dir: Path,
    tasks: tuple[str, ...],
    num_eval_samples: int | None,
    engine: str | None,
) -> None:
    """Score accuracy through the same driver `axzoo eval` uses.

    Deliberately not a local implementation: a second scoring path would produce a number
    that cannot be compared with the one the zoo reports for this model.
    """
    try:
        from axelera.zoo.build.config import LlmBuildConfig, LlmEvalConfig
        from axelera.zoo.eval.llm_runner import axgraph_target, run_llm_eval
    except ImportError as error:
        raise SystemExit(
            '--eval scores through the shared zoo eval driver; install `axelera-zoo[llm-eval]`.'
        ) from error

    target = axgraph_target(
        LlmBuildConfig(model_name=MODEL_NAME, compile_seq_len=COMPILE_SEQ_LEN), output_dir
    )
    result = run_llm_eval(
        target,
        LlmEvalConfig(tasks=tasks),
        engine_override=engine,
        num_eval_samples=num_eval_samples,
    )
    print(f'engines: {", ".join(result.engines)}   max_length: {result.max_length}')
    for row in result.rows:
        scores = '  '.join(f'{p}={row.scores.get(p, float("nan")):.4f}' for p in result.engines)
        delta = '' if row.delta is None else f'  delta={row.delta:+.4f}'
        print(f'  {row.task:<24} {row.metric:<20} {scores}{delta}')


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description='Build, run, or benchmark this LLM.')
    parser.add_argument('--output-dir', type=Path, default=OUTPUT_DIR)
    modes = parser.add_mutually_exclusive_group()
    modes.add_argument(
        '--build',
        action='store_true',
        help='Compile the model (minutes; the only action that writes)',
    )
    modes.add_argument('--run', action='store_true', help='Run deterministic greedy generation')
    modes.add_argument('--chat', action='store_true', help='Apply the tokenizer chat template')
    modes.add_argument('--benchmark', action='store_true', help='Measure token generation')
    modes.add_argument('--eval', action='store_true', help='Score accuracy on lm-eval tasks')
    parser.add_argument(
        '--tasks', nargs='+', default=None, help=f'lm-eval tasks to score (default {EVAL_TASKS})'
    )
    parser.add_argument(
        '--num-eval-samples', type=int, default=None, help='per-task sample cap for --eval'
    )
    parser.add_argument(
        '--engine',
        choices=EVAL_ENGINES,
        default=None,
        help='score one leg only: host (the fp reference, this machine) or aipu (the '
        'compiled model). Same two names every family uses, so a number from a recipe '
        'and a number from `axzoo eval` describe the same leg',
    )
    parser.add_argument(
        '--sample', action='store_true', help='Use sampling instead of greedy decode'
    )
    parser.add_argument('--prompt', default=None)
    parser.add_argument('--seq-len', type=int, default=None)
    parser.add_argument(
        '--workload',
        choices=('generate', 'prefill', 'decode'),
        default='generate',
        help='Benchmark workload. `generate` measures one realistic request; `prefill` and '
        '`decode` isolate a phase at --seq-len for the regression matrix.',
    )
    parser.add_argument('--max-new-tokens', type=int, default=None)
    parser.add_argument('--warmup', type=int, default=None)
    parser.add_argument('--iterations', type=int, default=None)
    parser.add_argument('--output-csv', type=Path, default=None)
    parser.add_argument('--json', action='store_true')
    parser.add_argument(
        '--cal-device',
        default=None,
        help="torch device for build-time calibration: 'cpu' / 'cuda'. NOT the Metis "
        'device - use --device-id for that.',
    )
    parser.add_argument(
        '--device-id',
        type=int,
        default=None,
        help='Axelera device used for run/chat (default 0)',
    )
    parser.add_argument(
        '--device-ids',
        type=int,
        nargs='+',
        default=None,
        help='Axelera devices used concurrently for benchmark (default 0)',
    )
    parser.add_argument('--no-load-to-device', action='store_true')
    parser.add_argument(
        '--quantized-model',
        type=Path,
        default=None,
        help='Reuse an already-quantized model (a `quantized_model/` dir saved by a prior '
        '--build, via AxModel.save) instead of loading + calibrating + quantizing again',
    )
    return parser


def main() -> None:
    parser = build_parser()
    args = parser.parse_args()
    action = (
        'benchmark'
        if args.benchmark
        else 'chat' if args.chat else 'run' if args.run else 'eval' if args.eval else 'build'
    )
    scoped_flags = (
        (args.sample, '--sample', ('run', 'chat'), '--run/--chat'),
        (args.prompt is not None, '--prompt', ('run', 'chat', 'benchmark'), 'generation actions'),
        (args.seq_len is not None, '--seq-len', ('build', 'benchmark'), 'build/--benchmark'),
        (args.workload != 'generate', '--workload', ('benchmark',), '--benchmark'),
        (
            args.max_new_tokens is not None,
            '--max-new-tokens',
            ('run', 'chat', 'benchmark'),
            'generation actions',
        ),
        (args.warmup is not None, '--warmup', ('benchmark',), '--benchmark'),
        (args.iterations is not None, '--iterations', ('benchmark',), '--benchmark'),
        (args.output_csv is not None, '--output-csv', ('benchmark',), '--benchmark'),
        (args.json, '--json', ('benchmark',), '--benchmark'),
        (args.cal_device is not None, '--cal-device', ('build',), 'build'),
        (args.device_id is not None, '--device-id', ('run', 'chat'), '--run/--chat'),
        (args.device_ids is not None, '--device-ids', ('benchmark',), '--benchmark'),
        (args.no_load_to_device, '--no-load-to-device', ('build',), 'build'),
        (
            args.quantized_model is not None,
            '--quantized-model',
            ('build',),
            'build',
        ),
        (args.tasks is not None, '--tasks', ('eval',), '--eval'),
        (args.num_eval_samples is not None, '--num-eval-samples', ('eval',), '--eval'),
        (args.engine is not None, '--engine', ('eval',), '--eval'),
    )
    for supplied, flag, allowed_actions, allowed_display in scoped_flags:
        if supplied and action not in allowed_actions:
            raise SystemExit(f'{flag} applies only to {allowed_display}')
    # Only once the flags themselves are valid: with no action, show the commands
    # rather than starting a multi-minute compile. `axzoo build` calls build_default().
    if not (args.build or args.run or args.chat or args.benchmark or args.eval):
        parser.print_help()
        return
    if args.benchmark:
        benchmark(
            args.output_dir,
            args.prompt,
            args.max_new_tokens if args.max_new_tokens is not None else 50,
            warmup=args.warmup if args.warmup is not None else 1,
            iterations=args.iterations if args.iterations is not None else 10,
            output_csv=args.output_csv,
            json_output=args.json,
            device_ids=tuple(args.device_ids) if args.device_ids is not None else (0,),
            workload=args.workload,
            seq_len=args.seq_len,
        )
        return
    if args.eval:
        evaluate(
            args.output_dir,
            tuple(args.tasks) if args.tasks else EVAL_TASKS,
            args.num_eval_samples,
            args.engine,
        )
        return
    if args.run or args.chat:
        run(
            args.output_dir,
            args.prompt if args.prompt is not None else DEFAULT_PROMPT,
            args.max_new_tokens if args.max_new_tokens is not None else 50,
            chat=args.chat,
            sample=args.sample,
            device_id=args.device_id if args.device_id is not None else 0,
        )
        return
    build(
        args.output_dir,
        args.seq_len if args.seq_len is not None else COMPILE_SEQ_LEN,
        args.cal_device,
        load_to_device=not args.no_load_to_device,
        quantized_model=args.quantized_model or QUANTIZED_MODEL,
    )


if __name__ == '__main__':
    main()
